//! Wolfram Rosenbrock replay.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/rosenbrock_golden.wls`) carries exact Rosenbrock values,
//! gradients and Hessians, per audit-sonium-solvers-optimization-20260921.
//! The Rosenbrock formulas below are an independent reimplementation (kept
//! separate from the crate's `test_functions` module on purpose); BFGS trajectories are
//! implementation-specific and asserted only by convergence to the analytic
//! minimizer (1, 1).

use serde::Deserialize;
use sonium_solvers_optimization::unconstrained::{BfgsConfig, bfgs};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Point {
    point: Vec<String>,
    value: String,
    gradient: Vec<String>,
    hessian: Vec<Vec<String>>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    minimizer: Vec<String>,
    points: Vec<Point>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Rosenbrock fixture");
    assert_eq!(
        fixture.schema,
        "sonium-solvers-optimization.wolfram-golden.v1"
    );
    fixture
}

fn rosenbrock(x: &[f64]) -> f64 {
    let (a, b) = (x[0], x[1]);
    (1.0 - a) * (1.0 - a) + 100.0 * (b - a * a) * (b - a * a)
}

fn rosenbrock_grad(x: &[f64]) -> Vec<f64> {
    let (a, b) = (x[0], x[1]);
    vec![
        -2.0 * (1.0 - a) - 400.0 * a * (b - a * a),
        200.0 * (b - a * a),
    ]
}

fn rosenbrock_hessian(x: &[f64]) -> [[f64; 2]; 2] {
    let (a, b) = (x[0], x[1]);
    [
        [2.0 - 400.0 * (b - 3.0 * a * a), -400.0 * a],
        [-400.0 * a, 200.0],
    ]
}

#[test]
fn rosenbrock_value_gradient_hessian_match_wolfram() {
    let fixture = parse_fixture();
    assert_eq!(fixture.points.len(), 5);
    for case in &fixture.points {
        let point: Vec<f64> = case.point.iter().map(|value| parse(value)).collect();
        let want_value = parse(&case.value);
        let got_value = rosenbrock(&point);
        assert!(
            (got_value - want_value).abs() <= 1e-12 * want_value.abs().max(1.0),
            "f({point:?}) = {got_value:e}, wolfram {want_value:e}"
        );
        let want_grad: Vec<f64> = case.gradient.iter().map(|value| parse(value)).collect();
        let got_grad = rosenbrock_grad(&point);
        for (index, (got, want)) in got_grad.iter().zip(want_grad.iter()).enumerate() {
            assert!(
                (got - want).abs() <= 1e-12 * want.abs().max(1.0),
                "grad[{index}] at {point:?}: {got:e} != {want:e}"
            );
        }
        let got_hessian = rosenbrock_hessian(&point);
        for (i, row) in case.hessian.iter().enumerate() {
            for (j, want) in row.iter().enumerate() {
                let want = parse(want);
                assert!(
                    (got_hessian[i][j] - want).abs() <= 1e-12 * want.abs().max(1.0),
                    "hessian[{i},{j}] at {point:?}"
                );
            }
        }
    }
}

#[test]
fn bfgs_converges_to_wolfram_minimizer() {
    let fixture = parse_fixture();
    let minimizer: Vec<f64> = fixture.minimizer.iter().map(|value| parse(value)).collect();
    assert_eq!(minimizer, vec![1.0, 1.0]);
    let result = bfgs(
        &rosenbrock,
        &rosenbrock_grad,
        &[-1.2, 1.0],
        &BfgsConfig::default(),
    )
    .expect("bfgs converged");
    for (got, want) in result.x.iter().zip(minimizer.iter()) {
        assert!(
            (got - want).abs() <= 1e-6,
            "bfgs x = {:?}, wolfram minimizer {minimizer:?}",
            result.x
        );
    }
    assert!(result.fun.abs() <= 1e-12, "bfgs fun = {}", result.fun);
}
